#include <vector>
#include <queue>

class Solution {
public:
    int secondMinimum(int n, std::vector<std::vector<int>>& edges, int time, int change) {
        std::vector<std::vector<int>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> dist1(n + 1, -1), dist2(n + 1, -1);
        dist1[1] = 0;
        std::queue<std::pair<int, int>> q;
        q.push({1, 0});

        while (!q.empty()) {
            auto [node, currTime] = q.front();
            q.pop();

            int period = currTime / change;
            if (period % 2 == 1) {
                currTime = (period + 1) * change;
            }
            int nextTime = currTime + time;

            for (int nxt : adj[node]) {
                if (dist1[nxt] == -1) {
                    dist1[nxt] = nextTime;
                    q.push({nxt, nextTime});
                } else if (dist2[nxt] == -1 && dist1[nxt] < nextTime) {
                    dist2[nxt] = nextTime;
                    if (nxt == n) return nextTime;
                    q.push({nxt, nextTime});
                }
            }
        }
        return dist2[n];
    }
};

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] dist1 = new int[n + 1];
        int[] dist2 = new int[n + 1];
        Arrays.fill(dist1, -1);
        Arrays.fill(dist2, -1);
        dist1[1] = 0;

        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{1, 0});

        while (!q.isEmpty()) {
            int[] top = q.poll();
            int node = top[0];
            int currTime = top[1];

            int period = currTime / change;
            if (period % 2 == 1) {
                currTime = (period + 1) * change;
            }
            int nextTime = currTime + time;

            for (int nxt : adj.get(node)) {
                if (dist1[nxt] == -1) {
                    dist1[nxt] = nextTime;
                    q.offer(new int[]{nxt, nextTime});
                } else if (dist2[nxt] == -1 && dist1[nxt] < nextTime) {
                    dist2[nxt] = nextTime;
                    if (nxt == n) return nextTime;
                    q.offer(new int[]{nxt, nextTime});
                }
            }
        }
        return dist2[n];
    }
}

