var secondMinimum = function(n, edges, time, change) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const dist1 = new Array(n + 1).fill(-1);
    const dist2 = new Array(n + 1).fill(-1);
    dist1[1] = 0;

    const q = [[1, 0]];
    let head = 0;

    while (head < q.length) {
        let [node, currTime] = q[head++];
        const period = Math.floor(currTime / change);
        if (period % 2 === 1) {
            currTime = (period + 1) * change;
        }
        const nextTime = currTime + time;

        for (const nxt of adj[node]) {
            if (dist1[nxt] === -1) {
                dist1[nxt] = nextTime;
                q.push([nxt, nextTime]);
            } else if (dist2[nxt] === -1 && dist1[nxt] < nextTime) {
                dist2[nxt] = nextTime;
                if (nxt === n) return nextTime;
                q.push([nxt, nextTime]);
            }
        }
    }
    return dist2[n];
